create table addresses (is_default boolean not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, user_id bigint not null, postal_code varchar(20), receiver_phone varchar(30) not null, country varchar(80) not null, city varchar(120) not null, province varchar(120) not null, address_line1 varchar(255) not null, address_line2 varchar(255), receiver_name varchar(255) not null, primary key (id));
create table appointments (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, slot_id bigint not null, therapist_id bigint not null, user_id bigint not null, status varchar(20) not null check ((status in ('PENDING','CONFIRMED','COMPLETED','CANCELLED'))), video_room_url varchar(500), notes text, primary key (id));
create table availability_slots (booked_count integer not null, capacity integer not null, is_booked boolean not null, end_time timestamp(6) with time zone not null, id bigint generated by default as identity, start_time timestamp(6) with time zone not null, therapist_id bigint not null, primary key (id));
create table banners (is_active boolean not null, sort_order integer not null, category_id bigint, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, image_url varchar(1024), subtitle varchar(255), title varchar(255) not null, primary key (id));
create table blog_categories (created_at timestamp(6), id bigint generated by default as identity, description varchar(255), name varchar(255) not null unique, slug varchar(255) not null unique, primary key (id));
create table blogs (is_featured boolean, reading_time_minutes integer, author_id bigint, category_id bigint, created_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), view_count bigint, content TEXT not null, meta_description TEXT, meta_title varchar(255), slug varchar(255) not null unique, status varchar(255) not null check ((status in ('DRAFT','PUBLISHED'))), summary TEXT, thumbnail_url varchar(255), title varchar(255) not null, primary key (id));
create table campaign_products (campaign_id bigint not null, product_id bigint not null);
create table campaigns (is_active boolean not null, created_at timestamp(6) with time zone not null, ends_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, title varchar(255) not null, primary key (id));
create table cart_items (qty integer not null, saved_for_later boolean not null, cart_id bigint not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, variant_id bigint not null, primary key (id), constraint uq_cart_variant unique (cart_id, variant_id));
create table carts (created_at timestamp(6) with time zone not null, discount_id bigint, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, user_id bigint not null unique, primary key (id));
create table categories (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, parent_id bigint, name varchar(120) not null, slug varchar(140) not null unique, primary key (id));
create table certificates (course_id bigint not null, id bigint generated by default as identity, issued_at timestamp(6) with time zone not null, user_id bigint not null, cert_number varchar(40) not null unique, primary key (id), constraint ux_cert_user_course unique (user_id, course_id));
create table clinic_homework (completed_at timestamp(6) with time zone, created_at timestamp(6) with time zone not null, due_date timestamp(6) with time zone, id bigint generated by default as identity, therapist_id bigint not null, user_id bigint not null, status varchar(20) not null check ((status in ('ASSIGNED','COMPLETED'))), title varchar(200) not null, description text, primary key (id));
create table clinic_messages (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, read_at timestamp(6) with time zone, therapist_id bigint not null, user_id bigint not null, sender_type varchar(20) not null check ((sender_type in ('PATIENT','THERAPIST'))), body text not null, primary key (id));
create table clinic_organization_seats (session_count integer not null, assigned_at timestamp(6) with time zone, assigned_user_id bigint, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, organization_id bigint not null, therapist_id bigint not null, assigned_email varchar(200), primary key (id));
create table course_enrollments (has_unseen_update boolean not null, course_id bigint not null, enrolled_at timestamp(6) with time zone not null, id bigint generated by default as identity, user_id bigint not null, primary key (id), constraint ux_enrollment_user_course unique (user_id, course_id));
create table course_lessons (duration_seconds integer not null, is_free_preview boolean not null, sort_order integer not null, id bigint generated by default as identity, section_id bigint not null, title varchar(200) not null, video_url varchar(500), resource_files jsonb, subtitles jsonb, video_variants jsonb, primary key (id));
create table course_quizzes (pass_score integer not null, course_id bigint not null unique, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, title varchar(200) not null, questions jsonb, primary key (id));
create table course_refund_requests (amount numeric(12,2) not null, course_id bigint not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, resolved_at timestamp(6) with time zone, user_id bigint not null, status varchar(20) not null check ((status in ('PENDING','APPROVED','REJECTED'))), admin_note text, reason text, primary key (id));
create table course_request_votes (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, request_id bigint not null, user_id bigint not null, primary key (id), unique (request_id, user_id));
create table course_requests (fulfilled boolean not null, like_count integer not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, requester_user_id bigint, requester_name varchar(120), title varchar(200) not null, description text, primary key (id));
create table course_sections (sort_order integer not null, course_id bigint not null, id bigint generated by default as identity, title varchar(200) not null, primary key (id));
create table course_waitlist (notified boolean not null, course_id bigint not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, notified_at timestamp(6) with time zone, user_id bigint not null, primary key (id), constraint ux_course_waitlist unique (course_id, user_id));
create table courses (capacity integer, discounted_price numeric(12,2), free_update_badge boolean not null, is_published boolean not null, job_market_badge boolean not null, price numeric(12,2) not null, requires_project_submission boolean not null, seats_taken integer not null, cohort_start_date timestamp(6) with time zone, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, product_id bigint, updated_at timestamp(6) with time zone not null, course_type varchar(20) not null check ((course_type in ('COURSE','SEMINAR','WORKSHOP'))), format varchar(20) not null check ((format in ('ONLINE_RECORDED','ONLINE_LIVE','IN_PERSON','OFFLINE'))), level varchar(20) check ((level in ('BEGINNER','INTERMEDIATE','ADVANCED'))), instructor_discount_code varchar(40), instructor varchar(120), title varchar(200) not null, slug varchar(220) not null unique, location varchar(300), instructor_skills varchar(500), thumbnail_url varchar(500), description text, instructor_bio text, primary key (id));
create table discounts (is_active boolean not null, max_discount_amount numeric(38,2), min_order_amount numeric(38,2), usage_count integer not null, usage_limit integer, value numeric(38,2) not null, created_at timestamp(6) with time zone not null, end_date timestamp(6) with time zone, id bigint generated by default as identity, start_date timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, code varchar(255) not null unique, type varchar(255) not null check ((type in ('PERCENTAGE','FIXED_AMOUNT'))), primary key (id));
create table favorites (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, product_id bigint not null, user_id bigint not null, primary key (id), constraint uc_user_product unique (user_id, product_id));
create table inventory (on_hand integer not null, reserved integer not null, version integer not null, updated_at timestamp(6) with time zone not null, variant_id bigint not null, primary key (variant_id));
create table journal_entries (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, shared_with_therapist_id bigint, user_id bigint not null, content text not null, primary key (id));
create table lesson_progress (completed boolean not null, last_position_seconds integer not null, course_id bigint not null, id bigint generated by default as identity, lesson_id bigint not null, updated_at timestamp(6) with time zone not null, user_id bigint not null, primary key (id), constraint ux_progress_user_lesson unique (user_id, lesson_id));
create table lesson_questions (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, lesson_id bigint not null, parent_id bigint, user_id bigint not null, content text not null, primary key (id));
create table lesson_quiz_attempts (passed boolean not null, score integer not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, lesson_id bigint not null, user_id bigint not null, primary key (id));
create table lesson_quizzes (pass_score integer not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, lesson_id bigint not null unique, title varchar(200) not null, questions jsonb, primary key (id));
create table memberships (created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone not null, id bigint generated by default as identity, started_at timestamp(6) with time zone not null, user_id bigint not null, tier varchar(20) not null check ((tier in ('GOLD'))), primary key (id));
create table messaging_plans (active boolean not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, therapist_id bigint not null, user_id bigint not null, primary key (id));
create table mood_checkins (mood_score integer not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, user_id bigint not null, note text, primary key (id));
create table option_type (id bigint generated by default as identity, name varchar(100) not null unique, primary key (id));
create table option_value (id bigint generated by default as identity, option_type_id bigint not null, value varchar(100) not null, primary key (id));
create table order_items (qty integer not null, unit_price_snapshot numeric(12,2) not null, id bigint generated by default as identity, order_id bigint not null, variant_id bigint not null, title_snapshot varchar(255) not null, options_snapshot jsonb, primary key (id));
create table order_status_history (at timestamp(6) with time zone not null, id bigint generated by default as identity, order_id bigint not null, status varchar(20) not null check ((status in ('PLACED','PROCESSING','SHIPPING','COMPLETED','CANCELLED'))), primary key (id));
create table orders (gateway_paid_amount numeric(12,2) default 0 not null, is_gift boolean not null, shipping_price numeric(12,2) not null, subtotal_price numeric(12,2) not null, total_price numeric(12,2) not null, wallet_paid_amount numeric(12,2) default 0 not null, created_at timestamp(6) with time zone not null, delivered_at timestamp(6) with time zone, id bigint generated by default as identity, shipped_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, user_id bigint not null, status varchar(20) not null check ((status in ('PLACED','PROCESSING','SHIPPING','COMPLETED','CANCELLED'))), shipping_carrier varchar(80), tracking_code varchar(120), gift_message text, address_snapshot jsonb not null, primary key (id));
create table organization_seats (assigned_at timestamp(6) with time zone, assigned_user_id bigint, course_id bigint not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, organization_id bigint not null, assigned_email varchar(200), primary key (id));
create table organizations (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, contact_email varchar(200), name varchar(200) not null, primary key (id));
create table patient_notes (appointment_id bigint not null, counselor_id bigint not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, note text not null, primary key (id));
create table patient_relations (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, therapist_id bigint not null, updated_at timestamp(6) with time zone not null, user_id bigint not null, tags jsonb, primary key (id), constraint ux_patient_relation_therapist_user unique (therapist_id, user_id));
create table payments (amount numeric(12,2) not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, order_id bigint, updated_at timestamp(6) with time zone not null, wallet_transaction_id bigint, status varchar(20) not null check ((status in ('PENDING','SUCCESS','FAILED'))), authority varchar(100) not null, ref_id varchar(100), primary key (id));
create table price_alerts (notified boolean not null, target_price numeric(12,2) not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, notified_at timestamp(6) with time zone, product_id bigint not null, user_id bigint not null, variant_id bigint not null, primary key (id), constraint ux_price_alert unique (variant_id, user_id));
create table product_bundles (is_active boolean not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, product_id bigint not null, updated_at timestamp(6) with time zone not null, title varchar(200) not null, slug varchar(220) not null unique, description text, member_product_ids jsonb, primary key (id));
create table product_images (sort_order integer not null, id bigint generated by default as identity, product_id bigint not null, url text not null, primary key (id));
create table product_questions (is_new boolean not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, parent_id bigint, product_id bigint not null, updated_at timestamp(6) with time zone not null, user_id bigint not null, content text not null, primary key (id));
create table product_review_helpful (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, review_id bigint not null, user_id bigint not null, primary key (id), constraint ux_review_helpful unique (review_id, user_id));
create table product_reviews (helpful_count integer not null, is_new boolean not null, rating integer, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, parent_id bigint, product_id bigint not null, updated_at timestamp(6) with time zone not null, user_id bigint not null, comment text not null, images jsonb not null, primary key (id));
create table product_variant_option_values (option_value_id bigint not null, product_variant_id bigint not null, primary key (option_value_id, product_variant_id));
create table product_variants (compare_at_price numeric(12,2), discounted_price numeric(12,2), is_active boolean not null, price numeric(12,2) not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, product_id bigint not null, updated_at timestamp(6) with time zone not null, sku varchar(80) not null unique, primary key (id));
create table product_videos (sort_order integer not null, id bigint generated by default as identity, product_id bigint not null, url text not null, primary key (id));
create table products (base_price numeric(12,2), discounted_price numeric(12,2), is_active boolean not null, category_id bigint, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, brand varchar(120), slug varchar(280) not null unique, description text, title varchar(255) not null, attributes jsonb, primary key (id));
create table project_peer_comments (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, submission_id bigint not null, user_id bigint not null, comment text not null, primary key (id));
create table project_submissions (course_id bigint not null, id bigint generated by default as identity, reviewed_at timestamp(6) with time zone, submitted_at timestamp(6) with time zone not null, user_id bigint not null, status varchar(20) not null check ((status in ('PENDING','APPROVED','REJECTED'))), file_url varchar(500) not null, mentor_feedback text, note text, primary key (id), constraint ux_project_submission_course_user unique (course_id, user_id));
create table psych_tests (discounted_price numeric(12,2), is_published boolean not null, price numeric(12,2) not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, product_id bigint, result_mode varchar(20) not null check ((result_mode in ('AUTO','COUNSELOR'))), title varchar(200) not null, slug varchar(220) not null unique, description text, questions jsonb, ranges jsonb, primary key (id));
create table quiz_attempts (passed boolean not null, score integer not null, course_id bigint not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, user_id bigint not null, primary key (id));
create table recently_viewed (id bigint generated by default as identity, product_id bigint not null, user_id bigint not null, viewed_at timestamp(6) with time zone not null, primary key (id), constraint uc_recently_viewed_user_product unique (user_id, product_id));
create table recurring_orders (interval_days integer not null, is_active boolean not null, qty integer not null, address_id bigint, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, last_order_id bigint, last_run_at timestamp(6) with time zone, next_run_at timestamp(6) with time zone not null, user_id bigint not null, variant_id bigint not null, primary key (id));
create table referral_rewards (amount numeric(12,2) not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, order_id bigint not null, referee_id bigint not null, referrer_id bigint not null, primary key (id), constraint ux_referral_reward_order unique (order_id));
create table refresh_tokens (created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone not null, id bigint generated by default as identity, revoked_at timestamp(6) with time zone, user_id bigint not null, token_hash varchar(64) not null unique, primary key (id));
create table return_requests (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, order_id bigint not null, order_item_id bigint not null, resolved_at timestamp(6) with time zone, user_id bigint not null, status varchar(20) not null check ((status in ('PENDING','APPROVED','REJECTED','COMPLETED'))), type varchar(20) not null check ((type in ('RETURN','EXCHANGE'))), admin_note text, reason text not null, primary key (id));
create table session_credits (remaining integer not null, id bigint generated by default as identity, therapist_id bigint not null, user_id bigint not null, primary key (id), constraint ux_credit_user_therapist unique (user_id, therapist_id));
create table stock_notifications (notified boolean not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, notified_at timestamp(6) with time zone, product_id bigint not null, user_id bigint not null, variant_id bigint not null, primary key (id), constraint ux_stock_notification unique (variant_id, user_id));
create table stories (is_active boolean not null, category_id bigint, created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone not null, id bigint generated by default as identity, product_id bigint, link_type varchar(20) default 'NONE' not null, media_type varchar(20) not null check ((media_type in ('IMAGE','VIDEO'))), title varchar(100), blog_slug varchar(200), media_url varchar(500) not null, primary key (id));
create table support_messages (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, ticket_id bigint not null, sender_role varchar(20) not null check ((sender_role in ('CUSTOMER','ADMIN'))), body text not null, primary key (id));
create table support_tickets (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, user_id bigint not null, status varchar(20) not null check ((status in ('OPEN','ANSWERED','CLOSED'))), subject varchar(200) not null, primary key (id));
create table therapist_match_questions (display_order integer not null, id bigint generated by default as identity, tag varchar(100) not null, question_text text not null, primary key (id));
create table therapist_switch_requests (created_at timestamp(6) with time zone not null, from_therapist_id bigint not null, id bigint generated by default as identity, resolved_at timestamp(6) with time zone, to_therapist_id bigint, user_id bigint not null, status varchar(20) not null check ((status in ('PENDING','APPROVED','REJECTED'))), admin_note text, reason text, primary key (id));
create table therapists (is_active boolean not null, session_duration_minutes integer not null, session_price numeric(12,2) not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, messaging_product_id bigint, product_id bigint, updated_at timestamp(6) with time zone not null, mode varchar(20) not null check ((mode in ('IN_PERSON','ONLINE','PHONE'))), name varchar(150) not null, specialty varchar(150), slug varchar(180) not null unique, location varchar(300), photo_url varchar(500), bio text, primary key (id));
create table user_psych_tests (total_score integer, completed_at timestamp(6) with time zone, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, interpreted_by_counselor_id bigint, test_id bigint not null, user_id bigint not null, status varchar(30) not null check ((status in ('PURCHASED','IN_PROGRESS','AWAITING_INTERPRETATION','COMPLETED'))), interpretation text, primary key (id));
create table users (is_active boolean not null, postal_code integer, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, otp_expiry timestamp(6) with time zone, referred_by_user_id bigint, reset_password_token_expiry timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, referral_code varchar(16), city varchar(50), first_name varchar(50), last_name varchar(50), email varchar(255) unique, otp_code varchar(255), password_hash varchar(255) not null, phone varchar(255) unique, reset_password_token varchar(255), role varchar(255) not null check ((role in ('CUSTOMER','ADMIN'))), primary key (id));
create table wallet_transactions (amount numeric(12,2) not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, wallet_id bigint not null, type varchar(20) not null check ((type in ('DEPOSIT','WITHDRAWAL','PURCHASE','REFUND','ADJUSTMENT'))), description varchar(255), reference_id varchar(255), primary key (id));
create table wallets (balance numeric(12,2) not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, user_id bigint not null unique, primary key (id));
create table withdrawal_requests (amount numeric(12,2) not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, user_id bigint not null, status varchar(20) not null check ((status in ('PENDING','APPROVED','PAID','REJECTED'))), iban varchar(26) not null, admin_note varchar(255), primary key (id));
